cd "$(dirname "$0")/.."
B="Transparent or plain pure white background, no ground, no shadow, no text, no borders."
bash tools/gen.sh zombie_attack "Pixel-art game sprite sheet: the SAME zombie as the reference image, shown 4 times side by side in ONE horizontal row, 4 equal columns, frames of a clawing ATTACK: frame1 leaning back with arms raised, frame2 lunging forward, frame3 claws slashing down in front, frame4 recovering. Side view facing right, identical size and feet baseline in every frame. $B" assets/raw/zombie_walk.png &
bash tools/gen.sh zombie_die "Pixel-art game sprite sheet: the SAME zombie as the reference image, shown 4 times side by side in ONE horizontal row, 4 equal columns, frames of a DEATH animation: frame1 recoiling from a hit, frame2 collapsing to knees, frame3 falling forward, frame4 lying face down on the ground. Side view facing right, same scale in every frame. $B" assets/raw/zombie_walk.png &
bash tools/gen.sh boar_die "Pixel-art game sprite sheet: the SAME boar as the reference image, shown 4 times side by side in ONE horizontal row, 4 equal columns, frames of a DEATH animation: frame1 flinching, frame2 stumbling, frame3 falling on its side, frame4 lying still on its side. Side view facing right, same scale in every frame. $B" assets/raw/boar_walk.png &
bash tools/gen.sh grass "Top-down seamless tileable ground texture for a game, 16-bit pixel art: lush green grass with small tufts, tiny flowers and a few pebbles, evenly lit, no shadows of objects, fills the entire square image edge to edge, must tile seamlessly." assets/raw/props.png &
wait; echo ALLDONE
